3	/**
4	 * Thrown by {@code RequireCityCapacity} when a create-owner request targets a city that already
5	 * contains the maximum number of owners (50). {@link CityAtCapacityExceptionHandler} reports a 409.
6	 */
7	public class CityAtCapacityException extends Exception {
8	
9	    private final String city;
10	
11	    public CityAtCapacityException(String city) {
12	        super("The city has reached its owner capacity: '" + city + "'");
13	        this.city = city;
14	    }
15	
16	    public String getCity() {
17	        return this.city;
18	    }
19	}
