9	/**
10	 * Assigns the owner's {@code bulkSignupWarning} — {@code true} when more than
11	 * {@code THRESHOLD} (80) owners had already been created on this owner's
12	 * {@code registrationDate} at the time of this create, otherwise {@code false}.
13	 * Runs after {@link DefaultOwnerRegistrationDate} so the date is populated and before
14	 * {@link SaveOwner} so the count reflects existing owners only.
15	 */
16	public class AssignOwnerBulkSignupWarning {
17	
18	    private static final int THRESHOLD = 80;
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        LocalDate registrationDate = owner.getRegistrationDate();
22	        long count = registrationDate == null ? 0 : ownerRepository.findAll().stream()
23	                .map(Owner::getRegistrationDate)
24	                .filter(registrationDate::equals)
25	                .count();
26	        owner.setBulkSignupWarning(count > THRESHOLD);
27	    }
28	}
